[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <meta name="description" content="Your neighborhood grocery store reimagined — unique, high-quality food products at great prices.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
  <link href="https://cdn.jsdelivr.net/npm/remixicon@4.6.0/fonts/remixicon.css" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --green: #2D6A4F;
      --green-dark: #1B4332;
      --green-light: #40916C;
      --orange: #F4A261;
      --orange-dark: #E76F51;
      --cream: #FEFAE0;
      --cream-dark: #F5F0D0;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-400: #9CA3AF;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 10px 30px rgba(0,0,0,0.1);
      --radius: 16px;
      --radius-sm: 10px;
      --radius-full: 9999px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      color: var(--gray-800);
      background: var(--cream);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    h1, h2, h3, h4, h5, h6 {
      font-family: 'Nunito', system-ui, sans-serif;
      line-height: 1.2;
    }

    img { display: block; max-width: 100%; }
    a { color: inherit; text-decoration: none; }
    button { cursor: pointer; font-family: inherit; }
    input { font-family: inherit; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ===== HEADER ===== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      background: rgba(254, 250, 224, 0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid rgba(45, 106, 79, 0.08);
      transition: box-shadow 0.3s ease;
    }

    .header.scrolled {
      box-shadow: 0 2px 20px rgba(0,0,0,0.06);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1.5rem;
      color: var(--green);
    }

    .logo-icon {
      width: 38px;
      height: 38px;
      background: var(--green);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--cream);
      font-size: 1.2rem;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 36px;
      list-style: none;
    }

    .nav-links a {
      font-weight: 500;
      font-size: 0.95rem;
      color: var(--gray-700);
      transition: color 0.2s;
      position: relative;
    }

    .nav-links a::after {
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 2px;
      background: var(--green);
      border-radius: 2px;
      transition: width 0.25s ease;
    }

    .nav-links a:hover { color: var(--green); }
    .nav-links a:hover::after { width: 100%; }

    .nav-cta {
      background: var(--green);
      color: var(--white) !important;
      padding: 10px 22px;
      border-radius: var(--radius-full);
      font-weight: 600 !important;
      font-size: 0.9rem !important;
      transition: background 0.2s, transform 0.2s !important;
    }

    .nav-cta::after { display: none !important; }
    .nav-cta:hover {
      background: var(--green-dark) !important;
      transform: translateY(-1px);
    }

    .mobile-toggle {
      display: none;
      background: none;
      border: none;
      font-size: 1.5rem;
      color: var(--green);
    }

    /* ===== HERO ===== */
    .hero {
      padding: 140px 0 80px;
      background: linear-gradient(135deg, var(--cream) 0%, #E8F5E9 50%, var(--cream-dark) 100%);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -120px;
      right: -80px;
      width: 500px;
      height: 500px;
      background: radial-gradient(circle, rgba(244,162,97,0.15) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -100px;
      left: -60px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(45,106,79,0.08) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero-inner {
      display: flex;
      align-items: center;
      gap: 60px;
      position: relative;
      z-index: 1;
    }

    .hero-content { flex: 1; max-width: 560px; }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(45,106,79,0.1);
      color: var(--green);
      padding: 8px 16px;
      border-radius: var(--radius-full);
      font-size: 0.85rem;
      font-weight: 600;
      margin-bottom: 24px;
    }

    .hero h1 {
      font-size: 3.5rem;
      font-weight: 800;
      color: var(--green-dark);
      margin-bottom: 20px;
      letter-spacing: -0.02em;
    }

    .hero h1 span {
      color: var(--orange);
    }

    .hero p {
      font-size: 1.2rem;
      color: var(--gray-600);
      line-height: 1.7;
      margin-bottom: 36px;
      max-width: 480px;
    }

    .hero-buttons {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 28px;
      border-radius: var(--radius-full);
      font-weight: 600;
      font-size: 1rem;
      border: none;
      transition: all 0.25s ease;
    }

    .btn-primary {
      background: var(--green);
      color: var(--white);
      box-shadow: 0 4px 14px rgba(45,106,79,0.3);
    }

    .btn-primary:hover {
      background: var(--green-dark);
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(45,106,79,0.35);
    }

    .btn-secondary {
      background: var(--white);
      color: var(--green);
      border: 2px solid var(--green);
    }

    .btn-secondary:hover {
      background: var(--green);
      color: var(--white);
      transform: translateY(-2px);
    }

    .hero-visual {
      flex: 1;
      max-width: 500px;
      position: relative;
    }

    .hero-image-main {
      width: 100%;
      height: 420px;
      background: linear-gradient(135deg, #A7C957 0%, #6A994E 100%);
      border-radius: 24px;
      overflow: hidden;
      box-shadow: var(--shadow-lg);
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .hero-image-main .hero-img-placeholder {
      font-size: 6rem;
      opacity: 0.3;
      color: var(--white);
    }

    .hero-float-card {
      position: absolute;
      background: var(--white);
      border-radius: var(--radius);
      padding: 16px 20px;
      box-shadow: var(--shadow-lg);
      display: flex;
      align-items: center;
      gap: 12px;
      animation: float 3s ease-in-out infinite;
    }

    .hero-float-card.card-1 {
      bottom: -20px;
      left: -30px;
    }

    .hero-float-card.card-2 {
      top: 30px;
      right: -20px;
      animation-delay: 1.5s;
    }

    .float-icon {
      width: 44px;
      height: 44px;
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.3rem;
    }

    .float-icon.green { background: rgba(45,106,79,0.1); color: var(--green); }
    .float-icon.orange { background: rgba(244,162,97,0.15); color: var(--orange-dark); }

    .float-text strong { display: block; font-size: 0.9rem; color: var(--gray-800); }
    .float-text span { font-size: 0.8rem; color: var(--gray-400); }

    @keyframes float {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-8px); }
    }

    /* ===== SECTION STYLING ===== */
    .section {
      padding: 80px 0;
    }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section-header h2 {
      font-size: 2.2rem;
      font-weight: 800;
      color: var(--green-dark);
      margin-bottom: 12px;
    }

    .section-header p {
      font-size: 1.1rem;
      color: var(--gray-600);
      max-width: 520px;
      margin: 0 auto;
    }

    /* ===== FEATURED PRODUCTS CAROUSEL ===== */
    .featured-products {
      background: var(--white);
    }

    .carousel-wrapper {
      position: relative;
      overflow: hidden;
    }

    .carousel-track {
      display: flex;
      gap: 24px;
      transition: transform 0.45s cubic-bezier(0.25, 0.46, 0.45, 0.94);
      padding: 8px 4px 16px;
    }

    .product-card {
      min-width: 260px;
      background: var(--cream);
      border-radius: var(--radius);
      overflow: hidden;
      transition: transform 0.3s ease, box-shadow 0.3s ease;
      flex-shrink: 0;
    }

    .product-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-lg);
    }

    .product-image {
      height: 200px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3.5rem;
      position: relative;
      overflow: hidden;
    }

    .product-info {
      padding: 20px;
    }

    .product-info h3 {
      font-size: 1.05rem;
      font-weight: 700;
      color: var(--gray-800);
      margin-bottom: 6px;
    }

    .product-info .product-desc {
      font-size: 0.85rem;
      color: var(--gray-400);
      margin-bottom: 14px;
      line-height: 1.5;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .product-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .product-price {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1.25rem;
      color: var(--green);
    }

    .product-add {
      width: 38px;
      height: 38px;
      border-radius: 50%;
      border: none;
      background: var(--green);
      color: var(--white);
      font-size: 1.2rem;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 0.2s, transform 0.2s;
    }

    .product-add:hover {
      background: var(--green-dark);
      transform: scale(1.1);
    }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 48px;
      height: 48px;
      border-radius: 50%;
      border: none;
      background: var(--white);
      color: var(--green);
      font-size: 1.3rem;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-md);
      z-index: 10;
      transition: all 0.2s;
    }

    .carousel-btn:hover {
      background: var(--green);
      color: var(--white);
      transform: translateY(-50%) scale(1.05);
    }

    .carousel-btn:disabled {
      opacity: 0.3;
      cursor: default;
    }

    .carousel-btn:disabled:hover {
      background: var(--white);
      color: var(--green);
      transform: translateY(-50%);
    }

    .carousel-btn.prev { left: -8px; }
    .carousel-btn.next { right: -8px; }

    /* ===== SEASONAL PICKS ===== */
    .seasonal-picks {
      background: var(--cream);
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .seasonal-card {
      background: var(--white);
      border-radius: var(--radius);
      overflow: hidden;
      transition: transform 0.3s ease, box-shadow 0.3s ease;
    }

    .seasonal-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .seasonal-image {
      height: 180px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
      position: relative;
    }

    .seasonal-badge {
      position: absolute;
      top: 12px;
      left: 12px;
      background: var(--orange);
      color: var(--white);
      font-size: 0.75rem;
      font-weight: 700;
      padding: 4px 12px;
      border-radius: var(--radius-full);
    }

    .seasonal-info {
      padding: 20px;
    }

    .seasonal-info h3 {
      font-size: 1rem;
      font-weight: 700;
      color: var(--gray-800);
      margin-bottom: 6px;
    }

    .seasonal-info .seasonal-desc {
      font-size: 0.85rem;
      color: var(--gray-400);
      margin-bottom: 12px;
      line-height: 1.5;
    }

    .seasonal-info .seasonal-price {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1.15rem;
      color: var(--green);
    }

    /* ===== CATEGORIES ===== */
    .categories {
      background: var(--white);
    }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 20px;
    }

    .category-card {
      position: relative;
      height: 220px;
      border-radius: var(--radius);
      overflow: hidden;
      cursor: pointer;
    }

    .category-bg {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3.5rem;
      transition: transform 0.4s ease;
    }

    .category-card:hover .category-bg {
      transform: scale(1.08);
    }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: rgba(27, 67, 50, 0.55);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      opacity: 0;
      transition: opacity 0.35s ease;
    }

    .category-card:hover .category-overlay {
      opacity: 1;
    }

    .category-label {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      padding: 16px;
      background: linear-gradient(transparent, rgba(0,0,0,0.6));
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      transition: opacity 0.35s ease;
    }

    .category-card:hover .category-label {
      opacity: 0;
    }

    .category-overlay h3 {
      color: var(--white);
      font-size: 1.1rem;
      font-weight: 700;
      margin-bottom: 6px;
    }

    .category-overlay p {
      color: rgba(255,255,255,0.85);
      font-size: 0.8rem;
      text-align: center;
      padding: 0 12px;
    }

    /* ===== BRAND HIGHLIGHTS ===== */
    .highlights {
      background: linear-gradient(135deg, var(--green-dark) 0%, var(--green) 50%, var(--green-light) 100%);
      padding: 72px 0;
      position: relative;
      overflow: hidden;
    }

    .highlights::before {
      content: '';
      position: absolute;
      top: -80px;
      right: -40px;
      width: 300px;
      height: 300px;
      background: radial-gradient(circle, rgba(244,162,97,0.15) 0%, transparent 70%);
      border-radius: 50%;
    }

    .highlights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 40px;
      position: relative;
      z-index: 1;
    }

    .highlight-item {
      text-align: center;
      color: var(--white);
    }

    .highlight-icon {
      width: 56px;
      height: 56px;
      margin: 0 auto 16px;
      background: rgba(255,255,255,0.15);
      border-radius: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.5rem;
    }

    .highlight-number {
      font-family: 'Nunito', sans-serif;
      font-size: 2.5rem;
      font-weight: 800;
      margin-bottom: 4px;
      line-height: 1;
    }

    .highlight-label {
      font-size: 1rem;
      font-weight: 600;
      margin-bottom: 6px;
    }

    .highlight-desc {
      font-size: 0.85rem;
      opacity: 0.75;
      line-height: 1.5;
    }

    /* ===== STORE LOCATOR ===== */
    .store-locator {
      background: var(--cream);
    }

    .locator-search {
      display: flex;
      gap: 12px;
      max-width: 520px;
      margin: 0 auto 40px;
    }

    .locator-search input {
      flex: 1;
      padding: 14px 20px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-full);
      font-size: 1rem;
      background: var(--white);
      transition: border-color 0.2s;
      outline: none;
    }

    .locator-search input:focus {
      border-color: var(--green);
    }

    .locator-search button {
      padding: 14px 32px;
      background: var(--green);
      color: var(--white);
      border: none;
      border-radius: var(--radius-full);
      font-weight: 600;
      font-size: 1rem;
      display: flex;
      align-items: center;
      gap: 8px;
      transition: background 0.2s, transform 0.2s;
    }

    .locator-search button:hover {
      background: var(--green-dark);
      transform: translateY(-1px);
    }

    .store-results {
      display: none;
      flex-direction: column;
      gap: 16px;
      max-width: 700px;
      margin: 0 auto;
    }

    .store-results.visible {
      display: flex;
    }

    .store-card {
      display: flex;
      align-items: center;
      gap: 20px;
      background: var(--white);
      padding: 24px;
      border-radius: var(--radius);
      box-shadow: var(--shadow-sm);
      transition: box-shadow 0.3s, transform 0.2s;
    }

    .store-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .store-icon-wrap {
      width: 52px;
      height: 52px;
      border-radius: 14px;
      background: rgba(45,106,79,0.1);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.4rem;
      color: var(--green);
      flex-shrink: 0;
    }

    .store-details { flex: 1; }

    .store-details h3 {
      font-size: 1.05rem;
      font-weight: 700;
      color: var(--gray-800);
      margin-bottom: 4px;
    }

    .store-details p {
      font-size: 0.9rem;
      color: var(--gray-400);
    }

    .store-meta {
      text-align: right;
      flex-shrink: 0;
    }

    .store-distance {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1.15rem;
      color: var(--green);
    }

    .store-hours {
      font-size: 0.8rem;
      color: var(--gray-400);
    }

    /* ===== NEWSLETTER ===== */
    .newsletter {
      background: var(--white);
    }

    .newsletter-inner {
      max-width: 600px;
      margin: 0 auto;
      text-align: center;
    }

    .newsletter-form {
      display: flex;
      gap: 12px;
      margin-top: 32px;
    }

    .newsletter-form input {
      flex: 1;
      padding: 14px 20px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-full);
      font-size: 1rem;
      background: var(--gray-50);
      outline: none;
      transition: border-color 0.2s, background 0.2s;
    }

    .newsletter-form input:focus {
      border-color: var(--green);
      background: var(--white);
    }

    .newsletter-form button {
      padding: 14px 32px;
      background: var(--orange);
      color: var(--white);
      border: none;
      border-radius: var(--radius-full);
      font-weight: 700;
      font-size: 1rem;
      transition: background 0.2s, transform 0.2s;
    }

    .newsletter-form button:hover {
      background: var(--orange-dark);
      transform: translateY(-1px);
    }

    .newsletter-success {
      display: none;
      align-items: center;
      justify-content: center;
      gap: 10px;
      margin-top: 20px;
      padding: 14px 24px;
      background: rgba(45,106,79,0.08);
      border-radius: var(--radius-sm);
      color: var(--green);
      font-weight: 600;
    }

    .newsletter-success.visible {
      display: flex;
    }

    /* ===== FOOTER ===== */
    .footer {
      background: var(--green-dark);
      color: var(--white);
      padding: 64px 0 0;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 1.5fr repeat(4, 1fr);
      gap: 48px;
      padding-bottom: 48px;
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }

    .footer-brand .logo {
      color: var(--white);
      margin-bottom: 16px;
    }

    .footer-brand .logo-icon {
      background: rgba(255,255,255,0.15);
    }

    .footer-brand p {
      font-size: 0.9rem;
      color: rgba(255,255,255,0.6);
      line-height: 1.6;
      margin-bottom: 20px;
    }

    .footer-socials {
      display: flex;
      gap: 12px;
    }

    .footer-socials a {
      width: 40px;
      height: 40px;
      border-radius: 10px;
      background: rgba(255,255,255,0.1);
